From ee3be3c8eb97b6d56b8266cb02fc976e468641ea Mon Sep 17 00:00:00 2001
From: Tad Hunt <tad@exablox.com>
Date: Wed, 2 Sep 2015 14:23:17 -0700
Subject: [PATCH] fix Apple OSX build issue

Fix build issue introduced by commit 9b0b8c1cbd1d945fb096d6130f18c99ca901e567
"Local variable names shadowed global function names (e.g. read),
this would cause compile errors with gcc 4.4.7."

diff --git a/src/lib/kinetic_socket.c b/src/lib/kinetic_socket.c
index 96ff7d33..a229e7d6 100644
--- a/src/lib/kinetic_socket.c
+++ b/src/lib/kinetic_socket.c
@@ -165,7 +165,7 @@ void KineticSocket_BeginPacket(int fd)
     int on = 1;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &on, sizeof(on));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }

@@ -175,6 +175,6 @@ void KineticSocket_FinishPacket(int fd)
     int off = 0;
     setsockopt(fd, IPPROTO_TCP, TCP_CORK, &off, sizeof(off));
 #else
-    (void)socket;
+    (void)fd;
 #endif
 }
-- 
2.25.1

You are a programming expert.

You will be given the root cause of a bug.

Based on these details, your task is to determine whether the provided code snippet contains the bug.
Think step by step.
Be conservative in your assessment. If you are unsure, answer "no."

Root cause:
The bug was caused by local variable names shadowing global function names, specifically the use of the name `socket`, which conflicted with the global function `socket()`. This shadowing led to compile errors when the compiler could not resolve which `socket` was being referenced, particularly in GCC version 4.4.7.



Now, determine whether the provided code snippet is buggy:
    (void)socket;
#endif
}

void KineticSocket_FinishPacket(int socket)
{
#if !defined(__APPLE__) /* TCP_CORK is NOT available on OSX */
    int off = 0;
    setsockopt(socket, IPPROTO_TCP, TCP_CORK, &off, sizeof(off));
#else
    (void)socket;
#endif
}


